using Licitaciones.Domain.Licitaciones;
using Licitaciones.Application.Ofertas;
namespace Licitaciones.Application.Licitaciones;
public sealed class GestionarLicitacionesService(ILicitacionRepository repo, IOfertaRepository ofertas, TimeProvider? reloj = null) { private readonly TimeProvider reloj = reloj ?? TimeProvider.System; public Task<IReadOnlyList<Licitacion>> ListarAsync(CancellationToken c = default) => repo.ListarAsync(c); public Task<Licitacion> ObtenerAsync(Guid id, CancellationToken c = default) => repo.ObtenerPorIdAsync(id, c).ContinueWith(t => t.Result ?? throw new LicitacionNoEncontradaException(), c); public async Task EditarAsync(Guid id, string codigo, string titulo, decimal presupuesto, DateTimeOffset cierre, CancellationToken c = default) { var l = await ObtenerAsync(id, c); var max = (await ofertas.ListarAsync(l.Id, null, c)).Select(x => x.MontoCrc).DefaultIfEmpty(0).Max(); if (presupuesto < max) throw new ArgumentException("El presupuesto no puede ser menor que una oferta existente."); l.Editar(codigo, titulo, presupuesto, cierre, reloj.GetUtcNow()); await repo.GuardarCambiosAsync(l, c); } public async Task EliminarAsync(Guid id, CancellationToken c = default) { var l = await ObtenerAsync(id, c); if ((await ofertas.ListarAsync(id, null, c)).Count > 0) throw new InvalidOperationException("No se puede eliminar una licitación con ofertas."); await repo.EliminarAsync(l, c); } }
